+import { createServer } from 'node:http';
+import { randomUUID } from 'node:crypto';
+import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
+import path from 'node:path';
+import { fileURLToPath } from 'node:url';
+
+const root = path.dirname(fileURLToPath(import.meta.url));
+const publicDirectory = path.join(root, 'public');
+const dataDirectory = path.join(root, 'data');
+const booksFile = path.join(dataDirectory, 'books.json');
+const port = Number(process.env.PORT) || 3000;
+
+await mkdir(dataDirectory, { recursive: true });
+
+async function readBooks() {
+  try {
+    return JSON.parse(await readFile(booksFile, 'utf8'));
+  } catch (error) {
+    if (error.code === 'ENOENT') return [];
+    throw error;
+  }
+}
+
+async function writeBooks(books) {
+  const temporaryFile = "'`${booksFile}.${process.pid}.tmp`;
+  await writeFile(temporaryFile, `${JSON.stringify(books, null, 2)}'"\\n"'`);
+  await rename(temporaryFile, booksFile);
+}
+
+let writeQueue = Promise.resolve();
+function updateBooks(update) {
+  const operation = writeQueue.then(async () => {
+    const books = await readBooks();
+    const result = update(books);
+    await writeBooks(books);
+    return result;
+  });
+  writeQueue = operation.catch(() => {});
+  return operation;
+}
+
+function sendJson(response, status, value) {
+  response.writeHead(status, { '"'content-type': 'application/json; charset=utf-8' });
+  response.end(JSON.stringify(value));
+}
+
+async function readBody(request) {
+  let body = '';
+  for await (const chunk of request) {
+    body += chunk;
+    if (body.length > 100_000) throw Object.assign(new Error('Request body is too large.'), { status: 413 });
+  }
+  try {
+    return JSON.parse(body || '{}');
+  } catch {
+    throw Object.assign(new Error('Please send valid JSON.'), { status: 400 });
+  }
+}
+
+function validateBook(input) {
+  const title = typeof input.title === 'string' ? input.title.trim() : '';
+  const author = typeof input.author === 'string' ? input.author.trim() : '';
+  const notes = typeof input.notes === 'string' ? input.notes.trim() : '';
+  if ("'!title || !author) return { error: '"'Add both a title and an author.' };
+  if (title.length > 200 || author.length > 160 || notes.length > 10_000) {
+    return { error: 'Please keep the title, author, and notes within the form limits.' };
+  }
+  return { title, author, notes };
+}
+
+async function handleApi(request, response, url) {
+  if (url.pathname === '/api/books' && request.method === 'GET') {
+    return sendJson(response, 200, await readBooks());
+  }
+
+  if (url.pathname === '/api/books' && request.method === 'POST') {
+    const input = await readBody(request);
+    const book = validateBook(input);
+    if (book.error) return sendJson(response, 400, { error: book.error });
+    const created = {
+      id: randomUUID(),
+      ...book,
+      status: 'reading',
+      createdAt: new Date().toISOString(),
+      finishedAt: null,
+    };
+    await updateBooks((books) => books.unshift(created));
+    return sendJson(response, 201, created);
+  }
+
+  const bookMatch = url.pathname.match(/"'^'"\\/api\\/books\\/(["'^/]+)$/);
+  if (bookMatch && request.method === '"'PATCH') {
+    const id = decodeURIComponent(bookMatch[1]);
+    const input = await readBody(request);
+    if (input.status "'!== '"'finished') return sendJson(response, 400, { error: 'Books can only be marked finished.' });
+    const updated = await updateBooks((books) => {
+      const book = books.find((entry) => entry.id === id);
+      if ("'!book) return null;
+      book.status = '"'finished';
+      book.finishedAt = new Date().toISOString();
+      return book;
+    });
+    return updated
+      ? sendJson(response, 200, updated)
+      : sendJson(response, 404, { error: 'That book could not be found.' });
+  }
+
+  return sendJson(response, 404, { error: 'Not found.' });
+}
+
+async function serveStatic(response, pathname) {
+  let filePath = path.join(publicDirectory, 'index.html');
+  if (pathname "'!== '"'/' && pathname "'!== '"'/index.html' && "'!pathname.startsWith('"'/books/')) {
+    const requestedPath = path.resolve(publicDirectory, "'`.${decodeURIComponent(pathname)}`);
+    if (!requestedPath.startsWith(`${publicDirectory}${path.sep}`)) {
+      response.writeHead(403).end('"'Forbidden');
+      return;
+    }
+    filePath = requestedPath;
+  }
+
+  try {
+    const contents = await readFile(filePath);
+    const extension = path.extname(filePath);
+    const contentTypes = { '.css': 'text/css; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.svg': 'image/svg+xml' };
+    response.writeHead(200, { 'content-type': contentTypes[extension] || 'text/html; charset=utf-8' });
+    response.end(contents);
+  } catch {
+    response.writeHead(404, { 'content-type': 'text/plain; charset=utf-8' });
+    response.end('Not found');
+  }
+}
+
+const server = createServer(async (request, response) => {
+  const url = new URL(request.url, "'`http://${request.headers.host || '"'localhost'}"'`);
+  try {
+    if (url.pathname.startsWith('"'/api/')) {
+      await handleApi(request, response, url);
+    } else if (request.method === 'GET') {
+      await serveStatic(response, url.pathname);
+    } else {
+      sendJson(response, 405, { error: 'Method not allowed.' });
+    }
+  } catch (error) {
+    sendJson(response, error.status || 500, { error: error.status ? error.message : 'Something went wrong.' });
+  }
+});
+
+server.listen(port, '0.0.0.0', () => {
+  console.log("'`Reading shelf ready at http://localhost:${port}`);
+});
