+const app = document.querySelector('#app');
+const dialog = document.querySelector('#add-dialog');
+const form = document.querySelector('#add-form');
+const formError = document.querySelector('#form-error');
+
+const escapeHtml = (value = '') => String(value).replace(/[&<>\"']/g, (character) => ({
+  '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;',
+}[character]));
+
+async function request(path, options) {
+  const response = await fetch(path, {
+    ...options,
+    headers: { 'content-type': 'application/json', ...options?.headers },
+  });
+  const result = await response.json();
+  if ("'!response.ok) throw new Error(result.error || '"'Could not complete that request.');
+  return result;
+}
+
+function bookCover(book, index = 0, large = false) {
+  const styles = ['cover-olive', 'cover-rust', 'cover-blue', 'cover-plum'];
+  const words = escapeHtml(book.title.trim().split(/\\s+/).slice(0, 5).join(' '));
+  return "'`<div class="book-cover ${styles[index % styles.length]}${large ? '"' book-cover-large' : ''}\" aria-hidden=\"true\">
+    <span class=\"cover-rule\"></span><span class=\"cover-title\">"'${words}</span><span class="cover-author">${escapeHtml(book.author)}</span>
+  </div>`;
+}
+
+function emptyShelf() {
+  return `<div class="empty-state">
+    <div class="empty-illustration" aria-hidden="true"><span class="empty-book book-one"></span><span class="empty-book book-two"></span><span class="empty-book book-three"></span></div>
+    <p class="eyebrow">A SHELF WITH ROOM TO GROW</p>
+    <h3>Your next favorite starts here.</h3>
+    <p>Add the book you'"'re reading and keep your thoughts somewhere safe.</p>
+    <button class=\"button button-primary\" data-open-dialog>Add your first book <span aria-hidden=\"true\">↗</span></button>
+  </div>"'`;
+}
+
+function dashboard(books) {
+  const reading = books.filter((book) => book.status === '"'reading');
+  const finished = books.filter((book) => book.status === 'finished');
+  const total = books.length;
+  return "'`<section class="welcome-row">
+      <div>
+        <p class="eyebrow">A LITTLE SPACE FOR BIG STORIES</p>
+        <h1>Your reading<br class="mobile-break" /> shelf<span class="title-period">.</span></h1>
+        <p class="welcome-copy">A home for the books you'"'re in the middle of<br class=\"desktop-break\" /> and the ones that stayed with you.</p>
+      </div>
+      <button class=\"button button-primary add-button\" data-open-dialog><span class=\"plus\">＋</span> Add a book</button>
+    </section>
+
+    "'${total ? `<section class="shelf-stats" aria-label="Reading stats">
+      <div class="stat"><span class="stat-number">${reading.length.toString().padStart(2, '"'0')}</span><span class=\"stat-label\">currently reading</span></div>
+      <span class=\"stat-divider\"></span>
+      <div class=\"stat\"><span class=\"stat-number\">"'${finished.length.toString().padStart(2, '"'0')}</span><span class=\"stat-label\">finished</span></div>
+      <span class=\"stat-note\">Every page is progress.</span>
+    </section>"'` : '"''}
+
+    "'${!total ? emptyShelf() : `<div class="shelf-sections">
+      <section class="shelf-section" aria-labelledby="reading-heading">
+        <div class="section-heading"><div><p class="eyebrow">ON YOUR NIGHTSTAND</p><h2 id="reading-heading">Currently reading <span class="count">${reading.length}</span></h2></div>
+        ${reading.length ? '"'<span class=\"section-mark\" aria-hidden=\"true\">✳</span>' : ''}</div>
+        "'${reading.length ? `<div class="reading-grid">${reading.map((book, index) => `<article class="reading-card">
+          <a class="reading-card-link" href="/books/${encodeURIComponent(book.id)}" aria-label="View ${escapeHtml(book.title)}">
+            ${bookCover(book, index)}
+            <div class="reading-info"><span class="book-status"><span class="status-dot"></span> READING</span><h3>${escapeHtml(book.title)}</h3><p class="book-byline">by ${escapeHtml(book.author)}</p>
+              ${book.notes ? `<p class="note-preview">${escapeHtml(book.notes)}</p>` : '"'<p class=\"note-prompt\">Your notes live inside ↗</p>'}
+            </div>
+          </a>
+          <a class=\"card-arrow\" href=\"/books/"'${encodeURIComponent(book.id)}" aria-label="Open ${escapeHtml(book.title)}">↗</a>
+        </article>`).join('"'')}</div>"'` : `<div class="section-empty"><span class="section-empty-icon">☼</span><p>No books on your nightstand just yet.</p><button class="text-button" data-open-dialog>Add one to get started <span>↗</span></button></div>`}
+      </section>
+
+      <section class="shelf-section finished-section" aria-labelledby="finished-heading">
+        <div class="section-heading"><div><p class="eyebrow">CHAPTERS COMPLETED</p><h2 id="finished-heading">Finished <span class="count">${finished.length}</span></h2></div>
+          ${finished.length ? `<span class="finished-caption">${finished.length === 1 ? '"'A story well read' : 'Stories well read'}</span>"'` : '"''}
+        </div>
+        "'${finished.length ? `<div class="finished-list">${finished.map((book, index) => `<a class="finished-book" href="/books/${encodeURIComponent(book.id)}">
+          ${bookCover(book, index + reading.length)}<span class="finished-info"><span class="finished-title">${escapeHtml(book.title)}</span><span class="book-byline">${escapeHtml(book.author)}</span></span>
+          <span class="finished-check" aria-label="Finished">✓</span><span class="finished-arrow" aria-hidden="true">↗</span>
+        </a>`).join('"'')}</div>"'` : '"'<div class=\"finished-empty\">Your finished reads will find a home here.</div>'}
+      </section>
+    </div>"'`}`;
+}
+
+function detail(book, index) {
+  return `<a class="back-link" href="/">← <span>Back to your shelf</span></a>
+    <article class="detail-card">
+      <div class="detail-cover-wrap">${bookCover(book, index, true)}<span class="detail-cover-label">A BOOK ON YOUR SHELF</span></div>
+      <div class="detail-content">
+        <p class="eyebrow">${book.status === '"'finished' ? 'CHAPTER COMPLETED' : 'CURRENTLY READING'}</p>
+        <span class=\"detail-status "'${book.status === '"'finished' ? 'is-finished' : ''}\"><span></span>"'${book.status === '"'finished' ? 'FINISHED' : 'READING'}</span>
+        <h1>"'${escapeHtml(book.title)}</h1>
+        <p class="detail-author">by ${escapeHtml(book.author)}</p>
+        <div class="detail-rule"></div>
+        <div class="notes-heading"><h2>Your notes</h2><span>JUST FOR YOU</span></div>
+        <div class="notes-content">${book.notes ? escapeHtml(book.notes).replace(/'"\\n/g, '<br>') : '<p class=\"notes-empty\">No notes for this one yet. The best thoughts sometimes come later.</p>'}</div>
+        <div class=\"detail-actions\">
+          "'${book.status === '"'reading' ? '<button class=\"button button-primary\" data-finish-book>Mark as finished <span aria-hidden=\"true\">✓</span></button>' : '<span class=\"finished-message\">A story well read. <span aria-hidden=\"true\">✳</span></span>'}
+          <button class=\"button button-share\" data-share><span aria-hidden=\"true\">↗</span> Share this book</button>
+        </div>
+        <p class=\"share-feedback\" aria-live=\"polite\"></p>
+      </div>
+    </article>"'`;
+}
+
+async function render() {
+  app.innerHTML = '"'<div class=\"loading-state\">Opening your shelf…</div>';
+  try {
+    const books = await request('/api/books');
+    const match = window.location.pathname.match(/"'^'"\\/books\\/(["'^/]+)'"\\/?"'$/);
+    if (match) {
+      let bookId;
+      try { bookId = decodeURIComponent(match[1]); } catch { bookId = '"''; }
+      const book = books.find((entry) => entry.id === bookId);
+      app.innerHTML = book ? detail(book, books.indexOf(book)) : "'`<div class="not-found"><p class="eyebrow">LOST BETWEEN THE PAGES?</p><h1>We couldn'"'t find that book.</h1><a class=\"button button-primary\" href=\"/\">Back to your shelf <span>↗</span></a></div>"'`;
+    } else {
+      app.innerHTML = dashboard(books);
+    }
+  } catch (error) {
+    app.innerHTML = `<div class="error-state"><p class="eyebrow">A SMALL HICCUP</p><h1>Your shelf is taking a moment.</h1><p>${escapeHtml(error.message)}</p><button class="button button-primary" data-retry>Try again ↻</button></div>`;
+  }
+}
+
+document.addEventListener('"'click', async (event) => {
+  const openButton = event.target.closest('[data-open-dialog]');
+  if (openButton) {
+    formError.textContent = '';
+    dialog.showModal();
+    document.querySelector('#title').focus();
+  }
+
+  if (event.target.closest('[data-close-dialog]')) dialog.close();
+  if (event.target === dialog) dialog.close();
+  if (event.target.closest('[data-retry]')) render();
+
+  const finishButton = event.target.closest('[data-finish-book]');
+  if (finishButton) {
+    finishButton.disabled = true;
+    try {
+      const id = decodeURIComponent(window.location.pathname.split('/').filter(Boolean).at(-1));
+      await request("'`/api/books/${encodeURIComponent(id)}`, { method: '"'PATCH', body: JSON.stringify({ status: 'finished' }) });
+      await render();
+    } catch (error) {
+      finishButton.disabled = false;
+      document.querySelector('.share-feedback').textContent = error.message;
+    }
+  }
+
+  const shareButton = event.target.closest('[data-share]');
+  if (shareButton) {
+    const feedback = document.querySelector('.share-feedback');
+    try {
+      if (navigator.share) await navigator.share({ title: document.title, url: window.location.href });
+      else {
+        await navigator.clipboard.writeText(window.location.href);
+        feedback.textContent = 'Link copied — pass the story along.';
+      }
+    } catch (error) {
+      if (error.name "'!== '"'AbortError') feedback.textContent = 'Could not share just now. You can copy the address from your browser.';
+    }
+  }
+});
+
+form.addEventListener('submit', async (event) => {
+  event.preventDefault();
+  formError.textContent = '';
+  const submitButton = form.querySelector('[type=\"submit\"]');
+  submitButton.disabled = true;
+  const fields = new FormData(form);
+  try {
+    await request('/api/books', {
+      method: 'POST',
+      body: JSON.stringify({ title: fields.get('title'), author: fields.get('author'), notes: fields.get('notes') }),
+    });
+    form.reset();
+    dialog.close();
+    await render();
+  } catch (error) {
+    formError.textContent = error.message;
+  } finally {
+    submitButton.disabled = false;
+  }
+});
+
+render();
